#![forbid(unsafe_code)]
//! Incremental comparison with freshly generated bytes, never parsing saved claims.

use fss_core::{ContentDigest, DigestAlgorithm, Sha256Hasher};
use std::io::{self, Read};

/// Saved data is input only. Native reproduction determines all lengths and semantics.
/// Any failure permanently fences this attempt; a fresh reader needs fresh admission.
pub(crate) struct ReportVerifier<R> {
    reader: R,
    expected: ContentDigest,
    maximum: u64,
    compared: u64,
    hash: Sha256Hasher,
    ended: bool,
}
impl<R: Read> ReportVerifier<R> {
    pub(crate) fn new(reader: R, expected: ContentDigest, maximum: u64) -> io::Result<Self> {
        if expected.algorithm() != DigestAlgorithm::Sha256 || maximum == 0 {
            return Err(io::Error::other(
                "bounded SHA-256 report verification required",
            ));
        }
        Ok(Self {
            reader,
            expected,
            maximum,
            compared: 0,
            hash: Sha256Hasher::new(),
            ended: false,
        })
    }

    /// Admit the entire native buffer before reading. Scratch never exceeds 4 KiB.
    pub(crate) fn compare(
        &mut self,
        native: &[u8],
        check: &mut impl FnMut() -> io::Result<()>,
    ) -> io::Result<()> {
        if self.ended {
            return Err(io::Error::other("report verification is fenced"));
        }
        let result = (|| {
            check()?;
            let length =
                u64::try_from(native.len()).map_err(|_| io::Error::other("report length"))?;
            if length > self.maximum.saturating_sub(self.compared) {
                return Err(io::Error::other("report verification allowance exhausted"));
            }
            let mut scratch = [0_u8; 4096];
            for chunk in native.chunks(scratch.len()) {
                let mut at = 0;
                while at < chunk.len() {
                    let n = read_bounded(&mut self.reader, &mut scratch[at..chunk.len()], check)?;
                    if n == 0 {
                        return Err(io::Error::other(
                            "saved report ended before native reproduction",
                        ));
                    }
                    at += n;
                }
                if &scratch[..chunk.len()] != chunk {
                    return Err(io::Error::other(
                        "saved report differs from native reproduction",
                    ));
                }
                self.hash.update(&scratch[..chunk.len()]);
                self.compared += chunk.len() as u64;
            }
            check()
        })();
        if result.is_err() {
            self.ended = true;
        }
        result
    }

    /// Call only after successful complete native analysis. Exact EOF and independently
    /// supplied digest are both mandatory. No zero-frame/prefix success is inferred here.
    pub(crate) fn finish(&mut self, check: &mut impl FnMut() -> io::Result<()>) -> io::Result<()> {
        if self.ended {
            return Err(io::Error::other("report verification is fenced"));
        }
        self.ended = true;
        if self.compared == 0 {
            return Err(io::Error::other("empty reproduction cannot verify"));
        }
        let mut suffix = [0_u8; 1];
        if read_bounded(&mut self.reader, &mut suffix, check)? != 0 {
            return Err(io::Error::other("saved report has a trailing suffix"));
        }
        let actual = ContentDigest::new(
            DigestAlgorithm::Sha256,
            self.hash
                .clone()
                .finalize()
                .map_err(|_| io::Error::other("report digest overflow"))?,
        );
        if actual != self.expected {
            return Err(io::Error::other(
                "saved report differs from independent expected SHA-256",
            ));
        }
        check()
    }
}

fn read_bounded(
    reader: &mut impl Read,
    bytes: &mut [u8],
    check: &mut impl FnMut() -> io::Result<()>,
) -> io::Result<usize> {
    for _ in 0..8 {
        check()?;
        match reader.read(bytes) {
            Ok(n) if n <= bytes.len() => return Ok(n),
            Ok(_) => return Err(io::Error::other("reader exceeded supplied buffer")),
            Err(e) if e.kind() == io::ErrorKind::Interrupted => {}
            Err(e) => return Err(e),
        }
    }
    Err(io::Error::other(
        "report read interruption allowance exhausted",
    ))
}

#[cfg(test)]
mod tests {
    use super::*;
    type Result = std::result::Result<(), Box<dyn std::error::Error>>;
    const NATIVE: &[u8] = b"header\nframe:0\nframe:1\ncomplete:true\n";
    fn verifier(saved: &[u8]) -> io::Result<ReportVerifier<&[u8]>> {
        ReportVerifier::new(saved, ContentDigest::sha256(saved), 1_000_000)
    }
    #[test]
    fn matching_incremental_reproduction_requires_eof_and_digest() -> Result {
        let mut v = verifier(NATIVE)?;
        for part in NATIVE.chunks(3) {
            v.compare(part, &mut || Ok(()))?;
        }
        v.finish(&mut || Ok(()))?;
        assert!(v.finish(&mut || Ok(())).is_err());
        assert!(v.compare(b"", &mut || Ok(())).is_err());
        Ok(())
    }
    #[test]
    fn rehashed_tampering_reordering_and_duplication_never_verify() -> Result {
        let bad = [
            b"header\nframe:1\nframe:0\ncomplete:true\n".as_slice(),
            b"header\nframe:0\nframe:0\ncomplete:true\n".as_slice(),
            b"header\nframe:X\nframe:1\ncomplete:true\n".as_slice(),
        ];
        for bytes in bad {
            let mut v = verifier(bytes)?;
            assert!(v.compare(NATIVE, &mut || Ok(())).is_err());
            assert!(v.finish(&mut || Ok(())).is_err());
        }
        Ok(())
    }
    #[test]
    fn independently_expected_digest_is_not_derived_from_saved_claims() -> Result {
        let mut v = ReportVerifier::new(NATIVE, ContentDigest::sha256(b"different"), 100)?;
        v.compare(NATIVE, &mut || Ok(()))?;
        assert!(v.finish(&mut || Ok(())).is_err());
        Ok(())
    }
    #[test]
    fn truncation_and_appended_suffix_fail_even_after_rehash() -> Result {
        let mut short = verifier(&NATIVE[..NATIVE.len() - 1])?;
        assert!(short.compare(NATIVE, &mut || Ok(())).is_err());
        let mut extended = NATIVE.to_vec();
        extended.push(b'\n');
        let mut long = verifier(&extended)?;
        long.compare(NATIVE, &mut || Ok(()))?;
        assert!(long.finish(&mut || Ok(())).is_err());
        Ok(())
    }
    #[test]
    fn empty_reproduction_and_over_limit_are_terminal() -> Result {
        let mut v = verifier(NATIVE)?;
        assert!(v.finish(&mut || Ok(())).is_err());
        let mut v = ReportVerifier::new(NATIVE, ContentDigest::sha256(NATIVE), 3)?;
        assert!(v.compare(NATIVE, &mut || Ok(())).is_err());
        assert_eq!(v.compared, 0);
        assert!(v.compare(&NATIVE[..3], &mut || Ok(())).is_err());
        Ok(())
    }
    struct Short<R> {
        inner: R,
        calls: usize,
        maximum: usize,
    }
    impl<R: Read> Read for Short<R> {
        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
            self.calls += 1;
            self.maximum = self.maximum.max(buf.len());
            if self.calls % 2 == 1 {
                return Err(io::ErrorKind::Interrupted.into());
            }
            let n = buf.len().min(7);
            self.inner.read(&mut buf[..n])
        }
    }
    #[test]
    fn short_reads_and_interruptions_use_bounded_scratch() -> Result {
        let data = vec![b'x'; 20_000];
        let reader = Short {
            inner: data.as_slice(),
            calls: 0,
            maximum: 0,
        };
        let mut v = ReportVerifier::new(reader, ContentDigest::sha256(&data), 20_000)?;
        v.compare(&data, &mut || Ok(()))?;
        v.finish(&mut || Ok(()))?;
        assert!(v.reader.maximum <= 4096);
        Ok(())
    }
    struct Interrupted {
        calls: usize,
    }
    impl Read for Interrupted {
        fn read(&mut self, _: &mut [u8]) -> io::Result<usize> {
            self.calls += 1;
            Err(io::ErrorKind::Interrupted.into())
        }
    }
    #[test]
    fn interruption_storm_is_bounded_and_fences_retry() -> Result {
        let mut v =
            ReportVerifier::new(Interrupted { calls: 0 }, ContentDigest::sha256(NATIVE), 100)?;
        assert!(v.compare(NATIVE, &mut || Ok(())).is_err());
        assert_eq!(v.reader.calls, 8);
        assert!(v.compare(NATIVE, &mut || Ok(())).is_err());
        assert_eq!(v.reader.calls, 8);
        Ok(())
    }
    #[test]
    fn cancellation_between_reads_and_at_final_eof_refuses() -> Result {
        let reader = Short {
            inner: NATIVE,
            calls: 0,
            maximum: 0,
        };
        let mut v = ReportVerifier::new(reader, ContentDigest::sha256(NATIVE), 100)?;
        let mut calls = 0;
        assert!(
            v.compare(NATIVE, &mut || {
                calls += 1;
                if calls == 4 {
                    Err(io::Error::other("cancel"))
                } else {
                    Ok(())
                }
            })
            .is_err()
        );
        assert!(v.finish(&mut || Ok(())).is_err());
        let mut v = verifier(NATIVE)?;
        v.compare(NATIVE, &mut || Ok(()))?;
        assert!(v.finish(&mut || Err(io::Error::other("cancel"))).is_err());
        assert!(v.finish(&mut || Ok(())).is_err());
        Ok(())
    }
}
